style.css:
@-moz-document url-prefix("https://scratch.mit.edu") {
/* Fundo da página */
    body, .site-container, .project-page {
        background-color: #ffd6e8 !important; /* rosa claro */
        color: #000 !important;
    }

    /* Barra superior e menus */
    .header, .top-bar, .site-nav, .dropdown-menu {
        background-color: #d16a8c !important; /* rosa escuro */
        color: #fff !important;
    }

    /* Botões gerais */
    button, .button, .ui-button, .btn, input[type="submit"] {
        background-color: #f497b2 !important; /* rosa fofo */
        color: #fff !important;
        border-radius: 15px !important;
        border: none !important;
        padding: 8px 15px !important;
        font-weight: bold;
        transition: 0.2s;
    }

    button:hover, .button:hover, .ui-button:hover, .btn:hover {
        background-color: #e8689c !important; /* rosa mais escuro ao passar o mouse */
    }

    /* Inputs e caixas de texto */
    input, textarea, select {
        border-radius: 10px !important;
        border: 1px solid #ff80a1 !important;
        background-color: #fff0f5 !important;
        color: #000 !important;
    }

    /* Seleção de texto */
    *::selection, *::-moz-selection {
        background-color: #ff80a1 !important;
        color: #fff !important;
    }

    /* Cards, painéis e áreas de conteúdo */
    .card, .panel, .workspace, .blocklyWorkspace, .studio {
        background-color: #ffd6e8 !important; /* fundo rosa claro */
        border-radius: 12px !important;
        color: #000 !important;
    }

    /* Blocos de programação */
    .blocklyBlockBackground, .blocklyText {
        fill: #f497b2 !important;
        color: #fff !important;
    }

    /* Scrollbars personalizadas */
    ::-webkit-scrollbar {
        width: 12px;
    }

    ::-webkit-scrollbar-track {
        background: #ffd6e8;
        border-radius: 10px;
    }

    ::-webkit-scrollbar-thumb {
        background-color: #e8689c;
        border-radius: 10px;
        border: 3px solid #ffd6e8;
    }

    /* Firefox scrollbars */
    * {
        scrollbar-width: thin !important;
        scrollbar-color: #e8689c #ffd6e8 !important;
    }
}
